state = "CLOSED"
failures = 0

def call_payment_provider():
    global state, failures
    if state == "OPEN":
        raise CircuitOpenError("paiement indisponible, échec rapide")
    try:
        return payment_api.charge()
    except TimeoutError:
        failures += 1
        if failures >= 5:
            state = "OPEN"  # isole la panne au lieu de bloquer tout le site
        raise
